package com.codepilot1c.core.search;
import static org.junit.Assert.*;import org.junit.Test;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import com.codepilot1c.core.tools.workspace.BackgroundJobRegistry;
public class Bm25SearchJobsTest {
 @Test public void coldSearchUsesExistingJobWithoutResubmission()throws Exception {Path root=Files.createTempDirectory("bm25-job-");var registry=BackgroundJobRegistry.createForTest();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);AtomicInteger calls=new AtomicInteger();try{var service=new Bm25SearchJobs(registry,(p,q,s,k,r)->{calls.incrementAndGet();entered.countDown();release.await();return Map.of("results",List.of(),"query",q);});var first=service.run(root,"valid","all",5,false,0);assertFalse((Boolean)first.get("terminal"));assertTrue(first.containsKey("next_call"));assertTrue(entered.await(2,TimeUnit.SECONDS));var again=service.run(root,"valid","all",5,false,0);assertEquals(first.get("job_id"),again.get("job_id"));assertEquals(1,calls.get());release.countDown();var done=registry.awaitStatus((String)first.get("job_id"),2000).orElseThrow();assertEquals("DONE",done.getState().name());var fresh=service.run(root,"valid","all",5,false,2000);assertTrue((Boolean)fresh.get("terminal"));assertNotEquals(first.get("job_id"),fresh.get("job_id"));assertEquals(2,calls.get());}finally{release.countDown();registry.shutdown();Files.delete(root);}}
 @Test public void failureIsNeverAnEmptySuccessfulSearch()throws Exception {Path root=Files.createTempDirectory("bm25-job-");var registry=BackgroundJobRegistry.createForTest();try{var service=new Bm25SearchJobs(registry,(p,q,s,k,r)->{throw new IllegalStateException("source quota exceeded");});assertThrows(IllegalStateException.class,()->service.run(root,"valid","modules",5,false,2000));}finally{registry.shutdown();Files.delete(root);}}
 @Test public void validationPrecedesBackgroundSubmission()throws Exception {Path root=Files.createTempDirectory("bm25-job-");var registry=BackgroundJobRegistry.createForTest();AtomicInteger calls=new AtomicInteger();try{var service=new Bm25SearchJobs(registry,(p,q,s,k,r)->{calls.incrementAndGet();return Map.of();});assertThrows(IllegalArgumentException.class,()->service.run(root,"и в на","all",5,false,0));assertThrows(IllegalArgumentException.class,()->service.run(root,"valid","all",30,false,0));assertEquals(0,calls.get());}finally{registry.shutdown();Files.delete(root);}}

 @Test public void searchQueueDoesNotOccupyGeneralBackgroundWorkers()throws Exception{var registry=BackgroundJobRegistry.createForTest();CountDownLatch release=new CountDownLatch(1),entered=new CountDownLatch(1);try{for(int i=0;i<4;i++)registry.startJob("project_bm25_search",()->{entered.countDown();release.await();return "{}";});assertTrue(entered.await(2,TimeUnit.SECONDS));String light=registry.startJob("ordinary_read",()->"{}");assertEquals("DONE",registry.awaitStatus(light,2000).orElseThrow().getState().name());}finally{release.countDown();registry.shutdown();}}
}
